//! JSON parser rejecting duplicate object keys at every nesting depth.
use serde::de::{self,Deserialize,Deserializer,Visitor,MapAccess,SeqAccess};
use serde_json::Value;
struct Strict(Value);
impl<'de> Deserialize<'de> for Strict{fn deserialize<D:Deserializer<'de>>(d:D)->std::result::Result<Self,D::Error>{struct V;impl<'de> Visitor<'de> for V{type Value=Strict;fn expecting(&self,f:&mut std::fmt::Formatter)->std::fmt::Result{f.write_str("JSON without duplicate keys")}fn visit_bool<E:de::Error>(self,v:bool)->std::result::Result<Strict,E>{Ok(Strict(v.into()))}fn visit_i64<E:de::Error>(self,v:i64)->std::result::Result<Strict,E>{Ok(Strict(v.into()))}fn visit_u64<E:de::Error>(self,v:u64)->std::result::Result<Strict,E>{Ok(Strict(v.into()))}fn visit_f64<E:de::Error>(self,v:f64)->std::result::Result<Strict,E>{serde_json::Number::from_f64(v).map(|n|Strict(Value::Number(n))).ok_or_else(||E::custom("non-finite JSON number"))}fn visit_str<E:de::Error>(self,v:&str)->std::result::Result<Strict,E>{Ok(Strict(v.into()))}fn visit_string<E:de::Error>(self,v:String)->std::result::Result<Strict,E>{Ok(Strict(v.into()))}fn visit_unit<E:de::Error>(self)->std::result::Result<Strict,E>{Ok(Strict(Value::Null))}fn visit_seq<A:SeqAccess<'de>>(self,mut a:A)->std::result::Result<Strict,A::Error>{let mut out=vec![];while let Some(v)=a.next_element::<Strict>()?{out.push(v.0)}Ok(Strict(Value::Array(out)))}fn visit_map<A:MapAccess<'de>>(self,mut a:A)->std::result::Result<Strict,A::Error>{let mut out=serde_json::Map::new();while let Some(k)=a.next_key::<String>()?{if out.contains_key(&k){return Err(de::Error::custom(format!("duplicate JSON key: {k}")))}out.insert(k,a.next_value::<Strict>()?.0);}Ok(Strict(Value::Object(out)))}}d.deserialize_any(V)}}
pub fn parse(bytes:&[u8])->crate::Result<Value>{Ok(serde_json::from_slice::<Strict>(bytes)?.0)}
#[cfg(test)]mod tests{use super::*;#[test]fn nested_duplicate_denied(){assert!(parse(br#"{"a":{"key":1,"key":2}}"#).is_err());}}
